head.b:skin:
/*
═══════════════════════════════════════════════════════
  Mediphera ميديفيرا — نظام التصميم (Medical Luxury)
  الألوان الأساسية (عدّليها من :root في الأسفل):
  primary  : #0F5E5A  (الأخضر الطبي)
  primary-dark : #0A3835
  gold     : #C9A227  (الذهبي الفاخر)
  cream    : #FAF7F1  (خلفية الكريمة)
═══════════════════════════════════════════════════════
*/
*{margin:0;padding:0;box-sizing:border-box}
:root{
  --primary:#0F5E5A;
  --primary-dark:#0A3835;
  --primary-soft:#EAF4F1;
  --gold:#C9A227;
  --gold-soft:#F6EED8;
  --cream:#FAF7F1;
  --white:#fff;
  --text:#26302E;
  --muted:#5E6E6A;
  --wa:#1FAF57;
  --wa-dark:#168A43;
  --radius:18px;
  --shadow:0 12px 32px rgba(10,56,53,.08);
  --shadow-lg:0 20px 48px rgba(10,56,53,.16);
  --container:1200px;
  --font:'Tajawal',system-ui,-apple-system,'Segoe UI',Arial,sans-serif;
}
html{scroll-behavior:smooth}
body{font-family:var(--font);background:var(--cream);color:var(--text);line-height:1.8;font-size:16px;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}
a{color:var(--primary);text-decoration:none;transition:color .25s,background .25s,transform .25s,box-shadow .25s}
a:hover{color:var(--primary-dark)}
::selection{background:var(--gold-soft);color:var(--primary-dark)}
.container{width:min(100% - 40px,var(--container));margin-inline:auto}
a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--gold);outline-offset:2px;border-radius:6px}

/* ── روابط التخطي (إمكانية الوصول) ── */
.skip-link{position:absolute;top:-100px;inset-inline-start:16px;background:var(--primary);color:#fff;padding:10px 18px;border-radius:10px;z-index:200;font-weight:700}
.skip-link:focus{top:12px;color:#fff}

/* ── الأزرار ── */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;font-family:var(--font);font-weight:700;font-size:15px;line-height:1;padding:14px 26px;border-radius:999px;border:2px solid transparent;cursor:pointer;white-space:nowrap}
.btn-primary{background:var(--primary);color:#fff}
.btn-primary:hover{background:var(--primary-dark);color:#fff;transform:translateY(-2px);box-shadow:0 10px 24px rgba(15,94,90,.25)}
.btn-wa{background:var(--wa);color:#fff}
.btn-wa:hover{background:var(--wa-dark);color:#fff;transform:translateY(-2px);box-shadow:0 10px 24px rgba(31,175,87,.32)}
.btn-ghost{background:transparent;color:var(--primary);border-color:var(--primary)}
.btn-ghost:hover{background:var(--primary);color:#fff}
.btn-sm{padding:10px 18px;font-size:13.5px}

/* ── الهيدر ── */
.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.93);backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);border-bottom:1px solid rgba(15,94,90,.08)}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:78px;position:relative}
.brand{display:flex;align-items:center;gap:12px;flex:none}
.brand-logo{width:46px;height:46px;border-radius:50%;object-fit:cover;border:2px solid var(--gold-soft);background:#fff;flex:none}
.brand-text{display:flex;flex-direction:column;line-height:1.35}
.brand-name{font-weight:800;font-size:20px;color:var(--primary-dark);letter-spacing:.5px}
.brand-tag{font-size:11.5px;color:var(--muted)}
.main-nav ul{display:flex;align-items:center;gap:26px}
.main-nav a{font-weight:700;font-size:14.5px;color:var(--text)}
.main-nav a:not(.btn):hover{color:var(--primary)}
.nav-toggle{display:none;flex-direction:column;gap:5px;background:none;border:0;cursor:pointer;padding:10px;z-index:120}
.nav-toggle span{width:24px;height:2.5px;background:var(--primary-dark);border-radius:2px;transition:.3s}

/* ── الهيرو ── */
.hero{background:linear-gradient(135deg,#FDFBF7 0%,#F4EEE2 55%,#EAF3EF 100%);position:relative;overflow:hidden}
.hero::before{content:"";position:absolute;top:-140px;inset-inline-end:-140px;width:480px;height:480px;border-radius:50%;background:radial-gradient(circle,rgba(201,162,39,.18),transparent 65%);pointer-events:none}
.hero-inner{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center;padding:84px 0 88px;position:relative}
.hero-eyebrow{display:inline-block;font-size:13px;font-weight:800;letter-spacing:.4px;color:var(--gold);background:var(--gold-soft);padding:7px 16px;border-radius:999px;margin-bottom:20px}
.hero-title{font-size:clamp(30px,4.6vw,52px);font-weight:800;line-height:1.4;color:var(--primary-dark);margin-bottom:18px}
.hero-title .hl{color:var(--primary);position:relative;white-space:nowrap}
.hero-title .hl::after{content:"";position:absolute;bottom:4px;inset-inline:0;height:10px;background:var(--gold-soft);z-index:-1;border-radius:4px}
.hero-sub{font-size:17px;color:var(--muted);max-width:560px;margin-bottom:30px}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:28px}
.hero-trust{display:flex;gap:10px 22px;flex-wrap:wrap;font-size:14px;font-weight:700;color:var(--primary-dark)}
.hero-trust li{list-style:none;display:flex;align-items:center;gap:8px}
.hero-trust li::before{content:"✓";color:var(--gold);font-weight:800}
.hero-media{position:relative}
.hero-img{border-radius:26px;box-shadow:var(--shadow-lg);width:100%;aspect-ratio:16/10;object-fit:cover}
.hero-badge{position:absolute;bottom:22px;inset-inline-start:-18px;background:#fff;border-radius:16px;box-shadow:var(--shadow-lg);padding:14px 20px;display:flex;flex-direction:column;line-height:1.5;border-inline-start:4px solid var(--gold)}
.hero-badge strong{font-size:15.5px;color:var(--primary-dark)}
.hero-badge span{font-size:12.5px;color:var(--muted)}

/* ── الأقسام ── */
.section{padding:84px 0}
.section-head{max-width:640px;margin:0 auto 48px;text-align:center}
.section-eyebrow{font-size:13px;font-weight:800;letter-spacing:.5px;color:var(--gold);margin-bottom:10px}
.section-title{font-size:clamp(24px,3.2vw,34px);font-weight:800;color:var(--primary-dark);line-height:1.4;margin-bottom:12px}
.section-sub{color:var(--muted);font-size:15.5px}
.section-more{margin-top:40px;text-align:center}

/* ── عن ميديفيرا ── */
.about-section{background:#fff}
.about-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:60px;align-items:center}
.about-media{position:relative}
.about-media img{border-radius:22px;box-shadow:var(--shadow-lg);width:100%;aspect-ratio:4/3;object-fit:cover}
.about-media::before{content:"";position:absolute;top:22px;bottom:-22px;inset-inline-start:-22px;width:100%;height:calc(100% - 0px);border:2px solid var(--gold-soft);border-radius:22px;z-index:-1}
.about-copy p{color:var(--muted);margin-bottom:16px;font-size:15.5px}
.about-copy p strong{color:var(--primary-dark)}
.about-points{margin:22px 0;display:grid;gap:12px}
.about-points li{list-style:none;position:relative;padding-inline-start:32px;font-weight:700;color:var(--text);font-size:15px}
.about-points li::before{content:"✓";position:absolute;inset-inline-start:0;top:3px;width:20px;height:20px;border-radius:50%;background:var(--primary-soft);color:var(--primary);font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:center}
.about-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:26px 0 30px}
.about-stats div{background:var(--cream);border:1px solid rgba(15,94,90,.08);border-radius:14px;padding:16px 10px;text-align:center}
.about-stats strong{display:block;font-size:24px;font-weight:800;color:var(--primary)}
.about-stats span{font-size:12px;color:var(--muted);font-weight:700}

/* ── شبكة المنتجات ── */
.products-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.product-card{background:#fff;border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);border:1px solid rgba(15,94,90,.06);transition:transform .3s,box-shadow .3s;display:flex;flex-direction:column}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg)}
.product-media{position:relative;overflow:hidden}
.product-media img{width:100%;aspect-ratio:1/1;object-fit:cover;transition:transform .5s}
.product-card:hover .product-media img{transform:scale(1.05)}
.product-media::after{content:"";position:absolute;top:0;inset-inline:0;height:4px;background:linear-gradient(90deg,var(--gold),rgba(201,162,39,.15))}
.product-body{padding:22px;display:flex;flex-direction:column;flex:1}
.product-name{font-size:17.5px;font-weight:800;color:var(--primary-dark);margin-bottom:8px}
.product-desc{font-size:13.8px;color:var(--muted);margin-bottom:14px;flex:1}
.product-chips{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:18px;padding:0}
.product-chips li{list-style:none;font-size:11.5px;font-weight:700;color:var(--primary);background:var(--primary-soft);padding:5px 11px;border-radius:999px}
.product-wa{align-self:stretch}

/* ── شبكة المقالات ── */
.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}
.post-card{background:#fff;border-radius:var(--radius);overflow:hidden;box-shadow:var(--shadow);border:1px solid rgba(15,94,90,.06);transition:transform .3s,box-shadow .3s;display:flex;flex-direction:column}
.post-card:hover{transform:translateY(-6px);box-shadow:var(--shadow-lg)}
.post-card-media{display:block;overflow:hidden}
.post-card-media img{width:100%;aspect-ratio:1/1;object-fit:cover;transition:transform .5s}
.post-card:hover .post-card-media img{transform:scale(1.05)}
.post-card-body{padding:22px;display:flex;flex-direction:column;flex:1}
.post-card-labels{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:10px;padding:0}
.chip{list-style:none;font-size:11.5px;font-weight:800;color:var(--gold);background:var(--gold-soft);padding:4px 12px;border-radius:999px}
a.chip:hover{background:var(--gold);color:#fff}
.post-card-title{font-size:17px;font-weight:800;line-height:1.6;margin-bottom:10px}
.post-card-title a{color:var(--primary-dark)}
.post-card-title a:hover{color:var(--primary)}
.post-card-snippet{font-size:13.5px;color:var(--muted);flex:1;margin-bottom:16px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.post-card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px dashed rgba(15,94,90,.15);padding-top:14px}
.post-card-date{font-size:12.5px;color:var(--muted)}
.read-more{font-size:13px;font-weight:800;color:var(--primary)}
.read-more:hover{color:var(--gold)}
.empty-note{background:#fff;border:2px dashed rgba(15,94,90,.2);border-radius:var(--radius);padding:48px;text-align:center;color:var(--muted);font-weight:700}
.pagination{display:flex;justify-content:center;gap:14px;margin-top:44px}

/* ── الأسئلة الشائعة ── */
.faq-section{background:#fff}
.faq-list{max-width:780px;margin:0 auto;display:grid;gap:14px}
.faq-list details{background:var(--cream);border:1px solid rgba(15,94,90,.08);border-radius:14px;overflow:hidden;transition:background .25s,box-shadow .25s}
.faq-list details[open]{background:#fff;box-shadow:var(--shadow);border-color:var(--gold-soft)}
.faq-list summary{cursor:pointer;list-style:none;display:flex;align-items:center;justify-content:space-between;gap:14px;padding:18px 22px;font-weight:800;font-size:15px;color:var(--primary-dark)}
.faq-list summary::-webkit-details-marker{display:none}
.faq-list summary::after{content:"+";font-size:24px;font-weight:400;color:var(--gold);transition:transform .25s;flex:none;line-height:1}
.faq-list details[open] summary::after{transform:rotate(45deg)}
.faq-list details p{padding:0 22px 20px;color:var(--muted);font-size:14.5px}

/* ── قسم التواصل ── */
.contact-section{background:linear-gradient(135deg,var(--primary-dark),var(--primary));color:#fff;position:relative;overflow:hidden}
.contact-section::before{content:"";position:absolute;top:-120px;inset-inline-start:-120px;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle,rgba(201,162,39,.25),transparent 65%);pointer-events:none}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center;position:relative}
.contact-copy .section-eyebrow{color:var(--gold)}
.contact-copy .section-title{color:#fff}
.contact-copy > p{color:rgba(255,255,255,.85);max-width:460px;margin-top:10px}
.contact-cards{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.contact-card{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:16px;padding:20px;text-align:center;backdrop-filter:blur(4px);transition:background .25s,transform .25s;display:block;color:#fff}
a.contact-card:hover{background:rgba(255,255,255,.16);transform:translateY(-4px);color:#fff}
.contact-card .card-icon{font-size:26px;display:block;margin-bottom:8px}
.contact-card strong{display:block;font-size:15px;margin-bottom:4px;color:#fff}
.contact-card span:not(.card-icon){font-size:12.5px;color:rgba(255,255,255,.75)}

/* ── الفوتر ── */
.site-footer{background:var(--primary-dark);color:rgba(255,255,255,.8)}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:40px;padding:64px 0 44px}
.footer-logo{width:54px;height:54px;border-radius:50%;margin-bottom:14px;background:#fff}
.footer-name{font-size:20px;font-weight:800;color:#fff;margin-bottom:10px}
.footer-name span{color:var(--gold);font-size:14px;margin-inline-start:6px}
.footer-brand p{font-size:13.5px;line-height:1.9;max-width:300px}
.socials{display:flex;gap:10px;margin-top:18px}
.social{width:40px;height:40px;border-radius:50%;background:rgba(255,255,255,.1);display:flex;align-items:center;justify-content:center;color:#fff;flex:none}
.social:hover{background:var(--gold);color:var(--primary-dark);transform:translateY(-3px)}
.social svg{width:18px;height:18px}
.footer-col h3{color:#fff;font-size:15.5px;font-weight:800;margin-bottom:16px;position:relative;padding-bottom:10px}
.footer-col h3::after{content:"";position:absolute;bottom:0;inset-inline-start:0;width:34px;height:2px;background:var(--gold)}
.footer-col ul{display:grid;gap:10px;font-size:13.8px}
.footer-col li{list-style:none}
.footer-col a{color:rgba(255,255,255,.75)}
.footer-col a:hover{color:var(--gold)}
.footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;border-top:1px solid rgba(255,255,255,.12);padding:20px 0;font-size:12.5px;color:rgba(255,255,255,.6)}

/* ── صفحة المقال/المنتج ── */
.article-wrap{padding:56px 0 84px}
.page-hero{background:linear-gradient(135deg,#FDFBF7,#EAF3EF);padding:54px 0;border-bottom:1px solid rgba(15,94,90,.07)}
.page-hero-title{font-size:clamp(24px,3.4vw,36px);font-weight:800;color:var(--primary-dark)}
.page-hero-sub{color:var(--muted);margin-top:6px;font-size:14.5px}
.post-article{max-width:820px;margin:0 auto;background:#fff;border-radius:22px;box-shadow:var(--shadow);overflow:hidden}
.article-head{padding:44px 48px 0}
.article-title{font-size:clamp(24px,3.4vw,34px);font-weight:800;line-height:1.5;color:var(--primary-dark);margin:12px 0 14px}
.article-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;font-size:13px;color:var(--muted);padding-bottom:24px;border-bottom:1px solid rgba(15,94,90,.08)}
.article-author{font-weight:800;color:var(--primary)}
.article-hero-image{margin:0}
.article-hero-image img{width:100%;aspect-ratio:16/8;object-fit:cover}
.article-body{padding:36px 48px 44px;font-size:16.5px;line-height:2;color:#33413E}
.article-body h2{font-size:23px;font-weight:800;color:var(--primary-dark);margin:34px 0 14px;position:relative;padding-inline-start:18px}
.article-body h2::before{content:"";position:absolute;inset-inline-start:0;top:8px;bottom:8px;width:5px;border-radius:4px;background:linear-gradient(var(--primary),var(--gold))}
.article-body h3{font-size:18.5px;font-weight:800;color:var(--primary);margin:26px 0 10px}
.article-body p{margin-bottom:16px}
.article-body ul,.article-body ol{margin:0 0 16px;padding-inline-start:26px}
.article-body ul{list-style:disc}
.article-body ol{list-style:decimal}
.article-body li{margin-bottom:8px}
.article-body img{border-radius:14px;margin:18px 0}
.article-body a{font-weight:700;text-decoration:underline;text-underline-offset:3px}
.article-body blockquote{border-inline-start:4px solid var(--gold);background:var(--gold-soft);padding:16px 22px;border-radius:0 12px 12px 0;margin:20px 0;font-weight:700;color:var(--primary-dark)}
.article-body table{width:100%;border-collapse:collapse;margin:20px 0;font-size:14.5px}
.article-body th{background:var(--primary-soft);color:var(--primary-dark)}
.article-body th,.article-body td{border:1px solid rgba(15,94,90,.12);padding:10px 14px;text-align:start}
.author-box{margin:0 48px;background:var(--cream);border:1px solid rgba(15,94,90,.08);border-radius:16px;padding:24px;display:flex;gap:18px;align-items:center}
.author-box-logo{width:64px;height:64px;border-radius:50%;object-fit:cover;background:#fff;border:2px solid var(--gold-soft);flex:none}
.author-box h3{font-size:16px;font-weight:800;color:var(--primary-dark);margin-bottom:2px}
.author-box-role{font-size:12.5px;color:var(--gold);font-weight:800;margin-bottom:8px}
.author-box p{font-size:13.5px;color:var(--muted);margin-bottom:12px}
.post-wa-cta{margin:28px 48px;background:linear-gradient(135deg,var(--primary-dark),var(--primary));border-radius:16px;padding:28px;text-align:center;color:#fff}
.post-wa-title{font-size:18px;font-weight:800;margin-bottom:14px}
.article-share{display:flex;align-items:center;gap:14px;padding:28px 48px 40px;font-size:14px;color:var(--muted);font-weight:700}
.article-share a{color:var(--primary);font-weight:800}

/* ── زر واتساب العائم ── */
.wa-float{position:fixed;bottom:22px;inset-inline-start:22px;z-index:99;width:56px;height:56px;border-radius:50%;background:var(--wa);display:flex;align-items:center;justify-content:center;box-shadow:0 10px 26px rgba(31,175,87,.4)}
.wa-float:hover{transform:scale(1.08)}
.wa-float svg{width:28px;height:28px;fill:#fff}

/* ── التجاوب ── */
@media (max-width:1020px){
  .products-grid,.posts-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr}
}
@media (max-width:920px){
  .nav-toggle{display:inline-flex}
  .main-nav{position:fixed;top:78px;left:0;right:0;background:#fff;max-height:0;overflow:hidden;transition:max-height .4s ease;box-shadow:var(--shadow-lg);z-index:110}
  .main-nav.open{max-height:calc(100vh - 78px);overflow:auto}
  .main-nav ul{flex-direction:column;align-items:stretch;gap:0;padding:10px 20px 20px}
  .main-nav li{border-bottom:1px solid rgba(15,94,90,.06)}
  .main-nav a{display:block;padding:13px 4px}
  .nav-cta{padding-top:14px}
  .nav-cta .btn{width:100%}
  .nav-toggle.open span:nth-child(1){transform:translateY(7.5px) rotate(45deg)}
  .nav-toggle.open span:nth-child(2){opacity:0}
  .nav-toggle.open span:nth-child(3){transform:translateY(-7.5px) rotate(-45deg)}
  .hero-inner{grid-template-columns:1fr;gap:40px;padding:56px 0 64px}
  .hero-media{order:2}
  .hero-badge{inset-inline-start:14px;bottom:14px}
  .about-grid,.contact-grid{grid-template-columns:1fr;gap:40px}
  .about-media::before{inset-inline-start:-10px}
  .article-head{padding:32px 26px 0}
  .article-body{padding:28px 26px 36px}
  .author-box,.post-wa-cta{margin-inline:26px}
  .article-share{padding:24px 26px 34px}
}
@media (max-width:600px){
  .products-grid,.posts-grid{grid-template-columns:1fr}
  .section{padding:60px 0}
  .hero-cta .btn{width:100%}
  .footer-grid{grid-template-columns:1fr;gap:32px}
  .footer-bottom{justify-content:center;text-align:center}
  .about-stats{gap:10px}
  .about-stats strong{font-size:20px}
  .header-inner{min-height:70px}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
}

body.script:
//
(function(){
  var t=document.querySelector('.nav-toggle');
  var n=document.querySelector('.main-nav');
  if(t&&n){
    t.addEventListener('click',function(){
      var open=n.classList.toggle('open');
      t.classList.toggle('open',open);
      t.setAttribute('aria-expanded',open?'true':'false');
    });
    n.querySelectorAll('a').forEach(function(a){
      a.addEventListener('click',function(){
        n.classList.remove('open');
        t.classList.remove('open');
        t.setAttribute('aria-expanded','false');
      });
    });
  }
  var y=document.getElementById('year');
  if(y){y.textContent=new Date().getFullYear();}
})();
//
